-- Story 5-1: CSV Reconciliation Upload -- Create reconciliation sessions table and SIS guides
-- ============================================= -- Reconciliation Sessions Table -- =============================================
CREATE TABLE IF NOT EXISTS daep_reconciliation_sessions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, uploaded_by TEXT NOT NULL, upload_date TIMESTAMPTZ DEFAULT NOW(), file_name TEXT NOT NULL, file_url TEXT NOT NULL, storage_path TEXT, -- Path in Supabase Storage bucket total_records INT DEFAULT 0, matched_count INT DEFAULT 0, discrepancy_count INT DEFAULT 0, new_in_sis_count INT DEFAULT 0, missing_from_sis_count INT DEFAULT 0, status TEXT DEFAULT 'uploading' CHECK (status IN ( 'uploading', 'mapping_required', 'parsing', 'comparing', 'in_review', 'completed', 'failed' )), detected_sis TEXT, -- Auto-detected SIS type from filename error_message TEXT, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW() );
-- Indexes CREATE INDEX idx_recon_sessions_tenant ON daep_reconciliation_sessions(tenant_id); CREATE INDEX idx_recon_sessions_status ON daep_reconciliation_sessions(status); CREATE INDEX idx_recon_sessions_date ON daep_reconciliation_sessions(upload_date DESC);
-- RLS ALTER TABLE daep_reconciliation_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "daep_reconciliation_sessions_tenant_isolation" ON daep_reconciliation_sessions FOR ALL USING ( tenant_id IN ( SELECT COALESCE(active_tenant_id, tenant_id) FROM user_profiles WHERE id = auth.uid()::text ) );
-- Updated_at trigger CREATE TRIGGER update_daep_reconciliation_sessions_updated_at BEFORE UPDATE ON daep_reconciliation_sessions FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
-- ============================================= -- SIS Guides Table (for step-by-step help) -- =============================================
CREATE TABLE IF NOT EXISTS sis_guides ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id TEXT REFERENCES tenants(id) ON DELETE CASCADE, -- NULL = global template sis_name TEXT NOT NULL CHECK (sis_name IN ('Skyward', 'Focus', 'PowerSchool', 'Ascender', 'Other')), title TEXT NOT NULL, overview TEXT, -- Markdown content steps JSONB NOT NULL DEFAULT '[]', -- Array of step objects field_mapping_hints JSONB, -- SIS field → DAEP field suggestions pdf_url TEXT, -- Optional pre-generated PDF URL is_active BOOLEAN DEFAULT true, updated_by TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW() );
-- Index for lookups CREATE INDEX idx_sis_guides_lookup ON sis_guides(sis_name, tenant_id);
-- RLS - Read access for authenticated users ALTER TABLE sis_guides ENABLE ROW LEVEL SECURITY;
CREATE POLICY "sis_guides_read_access" ON sis_guides FOR SELECT USING ( is_active = true AND ( tenant_id IS NULL OR -- Global guides visible to all tenant_id IN ( SELECT COALESCE(active_tenant_id, tenant_id) FROM user_profiles WHERE id = auth.uid()::text ) ) );
-- Updated_at trigger CREATE TRIGGER update_sis_guides_updated_at BEFORE UPDATE ON sis_guides FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
