// Upload file to Supabase Storage
const storagePath = `${tenantId}/${Date.now()}-${sanitizedFilename}`;

const { data: uploadData, error: uploadError } = await supabase.storage
  .from('daep-uploads')
  .upload(storagePath, file, {
    contentType: 'text/csv',
    upsert: false,
  });

if (uploadError) {
  return { success: false, error: 'Failed to upload file' };
}

// Get signed URL for access (7 days)
const { data: urlData } = await supabase.storage
  .from('daep-uploads')
  .createSignedUrl(storagePath, 60 * 60 * 24 * 7);

const signedUrl = urlData?.signedUrl || storagePath;


const SIS_PATTERNS: Record<string, RegExp[]> = {
  Skyward: [/skyward/i, /^sky_/i, /^skyw/i],
  Focus: [/focus/i, /^fcs_/i],
  PowerSchool: [/powerschool/i, /^ps_/i, /pschool/i],
  Ascender: [/ascender/i, /^asc_/i],
};

function detectSISFromFilename(filename: string): string | null {
  for (const [sis, patterns] of Object.entries(SIS_PATTERNS)) {
    if (patterns.some(p => p.test(filename))) {
      return sis;
    }
  }
  return null;
}


interface UploadState {
  progress: number;      // 0-100
  bytesUploaded: number;
  totalBytes: number;
  startTime: number;
  speed: number;         // bytes per second
  eta: number;           // seconds remaining
}

const updateProgress = (loaded: number, total: number, startTime: number) => {
  const elapsed = (Date.now() - startTime) / 1000;
  const speed = elapsed > 0 ? loaded / elapsed : 0;
  const remaining = total - loaded;
  const eta = speed > 0 ? remaining / speed : 0;

  return {
    progress: Math.round((loaded / total) * 100),
    bytesUploaded: loaded,
    totalBytes: total,
    speed,
    eta,
  };
};

const formatSpeed = (bps: number) => {
  if (bps > 1024 * 1024) return `${(bps / 1024 / 1024).toFixed(1)} MB/s`;
  return `${(bps / 1024).toFixed(1)} KB/s`;
};

const formatETA = (seconds: number) => {
  if (seconds < 60) return `${Math.ceil(seconds)}s`;
  return `${Math.ceil(seconds / 60)}m ${Math.ceil(seconds % 60)}s`;
};


