storage-bucket.settings:
-- Create bucket via Supabase Dashboard: -- 1. Go to Storage → New Bucket -- 2. Name: daep-uploads -- 3. Public: false (use signed URLs) -- 4. Max file size: 10MB (10485760 bytes) -- 5. Allowed MIME types: text/csv, application/vnd.ms-excel, text/plain
-- Storage RLS policies (via Dashboard or SQL): -- Allow authenticated users to upload to their tenant folder CREATE POLICY "tenant_upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK ( bucket_id = 'daep-uploads' AND (storage.foldername(name))[1] IN ( SELECT COALESCE(active_tenant_id, tenant_id) FROM user_profiles WHERE id = auth.uid()::text ) );
-- Allow read access for same tenant CREATE POLICY "tenant_read" ON storage.objects FOR SELECT TO authenticated USING ( bucket_id = 'daep-uploads' AND (storage.foldername(name))[1] IN ( SELECT COALESCE(active_tenant_id, tenant_id) FROM user_profiles WHERE id = auth.uid()::text ) );
